export const CONTRACT_VERSION = `${String(CONTRACT_MAJOR)}.${String(CONTRACT_MINOR)}`;

export type MethodName = keyof BridgeMethodTable;

export const BRIDGE_METHODS: readonly MethodName[] = bridgeNamespaces.flatMap((ns) =>
  ns.methods.map((m) => `${ns.name}.${m}` as MethodName),
);

