export function assertNever(value: never): never {
  throw new Error(`Unhandled case: ${String(value)}`);
}

export function isErrorCode(code: string): code is ErrorCode {
  const all: readonly string[] = [
    "UNKNOWN",
    "INTERNAL",
    "INVALID_PARAMS",
    "NOT_FOUND",
    "ALREADY_EXISTS",
    "CONFLICT_VERSION",
    "PERMISSION_DENIED",
    "AUTH_REQUIRED",
    "OAUTH_NOT_CONFIGURED",
    "REAUTH_REQUIRED",
    "OFFLINE",
    "RATE_LIMITED",
    "QUOTA_EXCEEDED",
    "TOO_LARGE_TO_EDIT",
    "UNSUPPORTED_OPERATION",
    "CANCELLED",
    "CONFIRMATION_REQUIRED",
    "PROVIDER_ERROR",
    "INTEGRITY_ERROR",
    "PATH_REJECTED",
    "SENSITIVE_CONTENT_BLOCKED",
    "AI_NOT_CONFIGURED",
    "AI_CONSENT_REQUIRED",
    "AI_BUDGET_EXCEEDED",
    "UI_INCOMPATIBLE",
  ];
  return all.includes(code);
}
